async fn original_history_received(
    receiver: &Arc<Node>,
    original: Arc<HashSet<crate::eventlog::EventId>>,
) -> bool {
    // Negative control: preserve the previous lossy observation until the
    // held-writer regression demonstrates why it cannot establish readiness.
