        Err(std::sync::TryLockError::Poisoned(_)) => panic!("received history mutex poisoned"),
    }
}

#[tokio::test]
async fn original_history_observation_waits_for_writer_without_blocking_network_runtime() {
    let (_dir, source, receiver) = sibling_nodes();
    source.enqueue_to_account(&source.account_id(), b"durable original", None).await.unwrap();
