p=Path('crates/mesh-talk-core/src/node/forwarding/tests.rs');s=p.read_text();at=s.index('#[tokio::test(flavor = "multi_thread", worker_threads = 4)]\nasync fn forwarding_to_group_')
new='''#[derive(Clone, Copy)]
enum RoutingSourceChange {
    Rename,
    Dissolve,
    ReplaceFullIdentity,
}

#[tokio::test]
async fn forwarding_prepares_stale_local_metadata_before_routing() {
    forwarding_after_signed_source_change(RoutingSourceChange::Rename).await;
}

#[tokio::test]
async fn forwarding_stale_local_metadata_cannot_bypass_dissolution() {
    forwarding_after_signed_source_change(RoutingSourceChange::Dissolve).await;
}

#[tokio::test]
async fn forwarding_stale_local_metadata_cannot_bypass_full_identity() {
    forwarding_after_signed_source_change(RoutingSourceChange::ReplaceFullIdentity).await;
}

async fn forwarding_after_signed_source_change(change: RoutingSourceChange) {
    let directory = tempfile::tempdir().unwrap();
    let account = Account::generate();
    let node = open(directory.path(), &account);
    let selected = source(&node);
    let group = node.create_channel("routing source", Vec::new()).await.unwrap();
    let target = ForwardTarget { kind: "channel".into(), target: hex::encode(group.as_bytes()) };
    let request = ForwardRequest {
        operation_id: format!("{}-source-change", super::super::node::now_millis()),
        source: selected,
        destinations: vec![target.clone()],
        mode: "individual".into(),
    };
    let mut advanced = false;
    let result = node.forward_messages_if(request.clone(), |commit| {
        commit()?;
        let acceptance_started = {
            let store = node.forwarding.lock().unwrap();
            store.batches.get(&request.operation_id).is_some_and(|batch| {
                batch.result.items.iter().any(|item| item.error.as_deref() == Some("Acceptance started"))
            })
        };
        if !advanced && acceptance_started {
            advanced = true;
            // A real owner-signed source advances after the durable batch has
            // begun but before local routing. There are no background workers
            // that could silently prepare this source for the routing reader.
            let (kind, payload) = match change {
                RoutingSourceChange::Rename => (EventKind::ChannelRename, b"new routing name".to_vec()),
                RoutingSourceChange::Dissolve => (EventKind::ChannelDissolve, Vec::new()),
                RoutingSourceChange::ReplaceFullIdentity => {
                    let mut replacement = node.identity.public();
                    replacement.x25519_pub = DeviceIdentity::generate().public().x25519_pub;
                    assert_eq!(replacement.user_id(), node.user_id());
                    assert_ne!(replacement, node.identity.public());
                    (EventKind::MembershipChange, crate::channel::ChannelMeta {
                        name: "replacement physical key".into(), members: vec![replacement],
                        epoch: 1, owner: node.user_id(),
                    }.encode())
                }
            };
            node.append_event(group, kind, payload)?;
            let book = node.channels.lock().unwrap();
            assert!(matches!(node.channel_identity_is_current(book.state(&group).unwrap()), Err(crate::eventlog::LogError::StaleCursor)), "the real source must invalidate routing readiness");
        }
        Ok(())
    }).await.unwrap();
    assert!(advanced, "the signed control must precede actual item routing");
    assert_eq!(result.items.len(), 2);
    let should_accept = matches!(change, RoutingSourceChange::Rename);
    for item in &result.items {
        let stale = item.error.as_deref().is_some_and(|value| value.contains("stale event page cursor"));
        assert_eq!(item.status == "accepted", should_accept, "routing status={} stale_projection={stale}", item.status);
        let id = item_identity(&request.operation_id, &target, &item.source_id);
        let delivery = node.delivery.lock().unwrap();
        let receipt = delivery.request(&id);
        if should_accept {
            let receipt = receipt.expect("accepted forwarding must have its original durable send receipt");
            assert_eq!(item.message_id.as_deref(), Some(receipt.message_id.to_hex().as_str()));
            assert!(item.error.is_none());
        } else {
            assert_eq!(item.status, "failed");
            assert!(item.message_id.is_none());
            assert!(receipt.is_none(), "a stale candidate cannot commit a rejected physical identity");
        }
    }
    let messages = node.log.lock().unwrap().events(&group).unwrap().into_iter().filter(|event| event.kind == EventKind::Message).count();
    assert_eq!(messages, if should_accept { 2 } else { 0 });
}

